36	func newTrailCmd() *cobra.Command {
37		var insecureHTTPAuth bool
38	
39		cmd := &cobra.Command{
40			Use:    "trail",
41			Short:  "Manage trails for your branches",
42			Hidden: true,
43			Args:   cobra.NoArgs,
44			Long: `Trails are branch-centric work tracking abstractions. They describe the
45	"why" and "what" of your work, while checkpoints capture the "how" and "when".
46	
47	Running 'entire trail' without a subcommand shows the trail for the current
48	branch, or lists recent trails if no trail exists for the current branch.`,
49			RunE: func(cmd *cobra.Command, _ []string) error {
50				return runTrailShow(cmd.Context(), cmd.OutOrStdout(), insecureHTTPAuth)
51			},
52		}
53	
54		cmd.PersistentFlags().BoolVar(&insecureHTTPAuth, "insecure-http-auth", false,
55			"Allow API calls over plain HTTP (insecure, for local development only)")
56		if err := cmd.PersistentFlags().MarkHidden("insecure-http-auth"); err != nil {
57			panic(fmt.Sprintf("hide insecure-http-auth flag: %v", err))
58		}
59	
60		cmd.AddCommand(newTrailListCmd())
61		cmd.AddCommand(newTrailCreateCmd())
62		cmd.AddCommand(newTrailUpdateCmd())
63		cmd.AddCommand(newTrailFindingCmd())
