69	// trailInsecureHTTP reads the persistent --insecure-http-auth flag from the trail root command.
70	func trailInsecureHTTP(cmd *cobra.Command) bool {
71		v, _ := cmd.Flags().GetBool("insecure-http-auth") //nolint:errcheck // flag is always registered
72		return v
73	}
