75	// trailListOptions are the inputs to runTrailListAll. Keeping them on a
76	// struct avoids a long positional argument list at the two call sites.
77	type trailListOptions struct {
78		Author       string
79		Status       string
80		JSON         bool
81		Limit        int
82		InsecureHTTP bool
83	}
