85	func defaultTrailListOptions(insecureHTTP bool) trailListOptions {
86		return trailListOptions{
87			Status:       defaultTrailListStatus,
88			Limit:        defaultTrailListLimit,
89			InsecureHTTP: insecureHTTP,
90		}
