93	// runTrailShow shows the trail for the current branch, or falls through to list.
94	func runTrailShow(ctx context.Context, w io.Writer, insecureHTTP bool) error {
95		branch, err := GetCurrentBranch(ctx)
96		if err != nil {
97			return runTrailListAll(ctx, w, defaultTrailListOptions(insecureHTTP))
98		}
99	
100		client, err := NewAuthenticatedAPIClient(ctx, insecureHTTP)
101		if err != nil {
102			return fmt.Errorf("authentication required: %w", err)
103		}
104	
105		forge, owner, repo, err := resolveTrailRemote(ctx)
106		if err != nil {
107			return err
108		}
109	
110		found, err := findTrailByBranch(ctx, client, forge, owner, repo, branch)
111		if err != nil {
112			return err
113		}
114		if found == nil {
115			return runTrailListAll(ctx, w, defaultTrailListOptions(insecureHTTP))
116		}
117	
118		printTrailDetails(w, found.ToMetadata())
119		return nil
120	}
