122	func printTrailDetails(w io.Writer, m *trail.Metadata) {
123		fmt.Fprintf(w, "Trail: %s\n", m.Title)
124		if m.Number > 0 {
125			fmt.Fprintf(w, "  Number:  %d\n", m.Number)
126		}
127		if !m.TrailID.IsEmpty() {
128			fmt.Fprintf(w, "  ID:      %s\n", m.TrailID)
129		}
130		fmt.Fprintf(w, "  Branch:  %s\n", m.Branch)
131		fmt.Fprintf(w, "  Base:    %s\n", m.Base)
132		fmt.Fprintf(w, "  Status:  %s\n", m.Status)
133		fmt.Fprintf(w, "  Author:  %s\n", m.AuthorLogin())
134		if m.Body != "" {
135			fmt.Fprintf(w, "  Body:    %s\n", m.Body)
136		}
137		if len(m.Labels) > 0 {
138			fmt.Fprintf(w, "  Labels:  %s\n", strings.Join(m.Labels, ", "))
139		}
140		if len(m.Assignees) > 0 {
141			fmt.Fprintf(w, "  Assignees: %s\n", strings.Join(m.Assignees, ", "))
142		}
143		fmt.Fprintf(w, "  Created: %s\n", m.CreatedAt.Format("2006-01-02T15:04:05Z07:00"))
144		fmt.Fprintf(w, "  Updated: %s\n", m.UpdatedAt.Format("2006-01-02T15:04:05Z07:00"))
145	}
