169	func runTrailListAll(ctx context.Context, w io.Writer, opts trailListOptions) error {
170		if opts.Limit <= 0 {
171			return errors.New("limit must be greater than 0")
172		}
173		statusFilters, err := parseTrailStatusFilter(opts.Status)
174		if err != nil {
175			return err
176		}
177		client, err := NewAuthenticatedAPIClient(ctx, opts.InsecureHTTP)
178		if err != nil {
179			return fmt.Errorf("authentication required: %w", err)
180		}
181	
182		forge, owner, repo, err := resolveTrailRemote(ctx)
183		if err != nil {
184			return err
185		}
186	
187		resp, err := client.Get(ctx, trailsBasePath(forge, owner, repo))
188		if err != nil {
189			return fmt.Errorf("failed to list trails: %w", err)
190		}
191		defer resp.Body.Close()
192		if err := checkTrailResponse(resp); err != nil {
193			return err
194		}
195	
196		var listResp api.TrailListResponse
197		if err := api.DecodeJSON(resp, &listResp); err != nil {
198			return fmt.Errorf("failed to decode trail list: %w", err)
199		}
200	
201		// Convert to metadata for display
202		trails := make([]*trail.Metadata, 0, len(listResp.Trails))
203		for i := range listResp.Trails {
204			trails = append(trails, listResp.Trails[i].ToMetadata())
205		}
206	
207		authorFilter := opts.Author
208		currentUserLogin := ""
209		if authorFilter == trailListAuthorMe {
210			login, err := fetchCurrentUserLogin(ctx, execRunner{})
211			if err != nil {
212				return err
213			}
214			currentUserLogin = login
215			authorFilter = login
216		}
217	
218		if authorFilter != "" {
219			trails = filterTrailsByAuthor(trails, authorFilter)
220		}
221	
222		if len(statusFilters) > 0 {
223			trails = filterTrailsByStatuses(trails, statusFilters)
224		}
225	
226		// Sort by updated_at descending, then keep only the most recent rows.
227		sort.Slice(trails, func(i, j int) bool {
228			return trails[i].UpdatedAt.After(trails[j].UpdatedAt)
229		})
230		trails = limitTrails(trails, opts.Limit)
231	
232		if opts.JSON {
233			enc := json.NewEncoder(w)
234			enc.SetIndent("", "  ")
235			if err := enc.Encode(trails); err != nil {
236				return fmt.Errorf("failed to encode JSON: %w", err)
237			}
238			return nil
239		}
240	
241		if len(trails) == 0 {
242			fmt.Fprintln(w, "No trails found.")
243			fmt.Fprintln(w)
244			fmt.Fprintln(w, "Commands:")
245			fmt.Fprintln(w, "  entire trail create   Create a trail for the current branch")
246			fmt.Fprintln(w, "  entire trail list     List recent trails")
247			fmt.Fprintln(w, "  entire trail update   Update trail metadata")
248			return nil
249		}
250	
251		printTrailList(w, trails, trailListDisplayOptions{
252			RequestedAuthor: authorFilter,
253			CurrentUser:     currentUserLogin,
254			StatusFilters:   statusFilters,
255		})
256	
257		return nil
258	}
