267	// filterTrailsByAuthor matches case-insensitively because GitHub logins are
268	// case-insensitive (e.g. "Alice" and "alice" identify the same user).
269	func filterTrailsByAuthor(trails []*trail.Metadata, login string) []*trail.Metadata {
270		var filtered []*trail.Metadata
271		for _, t := range trails {
272			if strings.EqualFold(t.AuthorLogin(), login) {
273				filtered = append(filtered, t)
274			}
275		}
276		return filtered
277	}
278	
279	func filterTrailsByStatus(trails []*trail.Metadata, status trail.Status) []*trail.Metadata {
280		var filtered []*trail.Metadata
281		for _, t := range trails {
282			if t.Status == status {
283				filtered = append(filtered, t)
284			}
285		}
286		return filtered
287	}
288	
289	func filterTrailsByStatuses(trails []*trail.Metadata, statuses []trail.Status) []*trail.Metadata {
290		statusSet := make(map[trail.Status]bool, len(statuses))
291		for _, status := range statuses {
292			statusSet[status] = true
293		}
294	
295		var filtered []*trail.Metadata
296		for _, t := range trails {
297			if statusSet[t.Status] {
298				filtered = append(filtered, t)
299			}
300		}
301		return filtered
302	}
303	
304	func parseTrailStatusFilter(filter string) ([]trail.Status, error) {
305		if filter == "" || filter == trailListStatusAny {
306			return nil, nil
307		}
308	
309		parts := strings.Split(filter, ",")
310		statuses := make([]trail.Status, 0, len(parts))
311		seen := make(map[trail.Status]bool, len(parts))
312		for _, part := range parts {
313			name := strings.TrimSpace(part)
314			if name == "" {
315				return nil, fmt.Errorf("invalid status filter %q: empty status", filter)
316			}
317			status := trail.Status(name)
318			if !status.IsValid() {
319				return nil, fmt.Errorf("invalid status %q: valid values are %s", name, formatValidStatuses())
320			}
321			if seen[status] {
322				continue
323			}
324			seen[status] = true
325			statuses = append(statuses, status)
326		}
327		return statuses, nil
328	}
