330	// fetchCurrentUserLogin resolves --author me to a GitHub login via the local
331	// gh CLI. The runner is injectable so tests can stub gh without touching the
332	// process environment.
333	func fetchCurrentUserLogin(ctx context.Context, runner bootstrapRunner) (string, error) {
334		login, err := ghCurrentUser(ctx, runner)
335		if err != nil {
336			return "", fmt.Errorf("resolve --author %s via gh CLI: %w\nhint: pass --author <login> explicitly if gh is unavailable", trailListAuthorMe, err)
337		}
338		if login == "" {
339			return "", errors.New("resolve --author me: gh returned an empty login")
340		}
341		return login, nil
342	}
