344	type trailListDisplayOptions struct {
345		RequestedAuthor string
346		CurrentUser     string
347		StatusFilters   []trail.Status
348	}
349	
350	func printTrailList(w io.Writer, trails []*trail.Metadata, opts trailListDisplayOptions) {
351		showAuthor := opts.RequestedAuthor == ""
352		// Group by status when the user filtered for 0 or 2+ statuses. A single
353		// status is already named in the header, so flat rows read more cleanly.
354		grouped := len(opts.StatusFilters) != 1
355		printTrailListHeader(w, opts, len(trails))
356		fmt.Fprintln(w)
357		if !grouped {
358			printTrailRows(w, trails, showAuthor)
359			return
360		}
361	
362		rendered := make(map[*trail.Metadata]bool, len(trails))
363		for _, status := range trailListStatusOrder(opts.StatusFilters) {
364			group := filterTrailsByStatus(trails, status)
365			if len(group) == 0 {
366				continue
367			}
368			for _, t := range group {
369				rendered[t] = true
370			}
371			fmt.Fprintf(w, "  %s · %d\n", trailStatusTitle(status), len(group))
372			fmt.Fprintln(w)
373			printTrailRows(w, group, showAuthor)
374			fmt.Fprintln(w)
375		}
376	
377		// When no explicit status filter is set, surface trails with unknown
378		// statuses in an "Other" bucket so they don't silently disappear if the
379		// server adds a status the CLI hasn't learned about yet.
380		if len(opts.StatusFilters) == 0 {
381			var other []*trail.Metadata
382			for _, t := range trails {
383				if !rendered[t] {
384					other = append(other, t)
385				}
386			}
387			if len(other) > 0 {
388				fmt.Fprintf(w, "  Other · %d\n", len(other))
389				fmt.Fprintln(w)
390				printTrailRows(w, other, showAuthor)
391				fmt.Fprintln(w)
392			}
393		}
394	}
