396	func printTrailListHeader(w io.Writer, opts trailListDisplayOptions, count int) {
397		if opts.RequestedAuthor == "" {
398			if len(opts.StatusFilters) == 0 {
399				fmt.Fprintf(w, "  Recent %s · %d\n", pluralize("trail", count), count)
400				return
401			}
402			fmt.Fprintf(w, "  %s · %d %s\n", trailStatusListTitle(opts.StatusFilters), count, pluralize("trail", count))
403			return
404		}
405	
406		label := opts.RequestedAuthor
407		// When --author me resolves to the same login the server already returned
408		// for the trail, render "Your trails (login)" so identity drift between
409		// gh and Entire is visible at a glance.
410		if opts.CurrentUser != "" && strings.EqualFold(opts.RequestedAuthor, opts.CurrentUser) {
411			label = fmt.Sprintf("Your trails (%s)", opts.CurrentUser)
412		}
413		if len(opts.StatusFilters) == 0 {
414			fmt.Fprintf(w, "  %s · %d\n", label, count)
415			return
416		}
417		fmt.Fprintf(w, "  %s · %d %s\n", label, count, trailStatusListDisplay(opts.StatusFilters))
418	}
