420	func printTrailRows(w io.Writer, trails []*trail.Metadata, showAuthor bool) {
421		// tabwriter aligns by display columns instead of bytes, so multi-byte
422		// branch names or logins don't throw off the table.
423		tw := tabwriter.NewWriter(w, 0, 0, 2, ' ', 0)
424		if showAuthor {
425			fmt.Fprintln(tw, "  NUM\tBRANCH\tTITLE\tAUTHOR\tUPDATED")
426		} else {
427			fmt.Fprintln(tw, "  NUM\tBRANCH\tTITLE\tUPDATED")
428		}
429		for _, t := range trails {
430			number := "-"
431			if t.Number > 0 {
432				number = strconv.Itoa(t.Number)
433			}
434			title := truncateOneLine(t.Title, 60)
435			if title == "" {
436				title = "(untitled)"
437			}
438			if showAuthor {
439				fmt.Fprintf(tw, "  %s\t%s\t%s\t%s\t%s\n", number, t.Branch, title, t.AuthorLogin(), timeAgo(t.UpdatedAt))
440				continue
441			}
442			fmt.Fprintf(tw, "  %s\t%s\t%s\t%s\n", number, t.Branch, title, timeAgo(t.UpdatedAt))
443		}
444		_ = tw.Flush()
445	}
