447	func trailListStatusOrder(filter []trail.Status) []trail.Status {
448		order := []trail.Status{
449			trail.StatusInProgress,
450			trail.StatusOpen,
451			trail.StatusInReview,
452			trail.StatusDraft,
453			trail.StatusMerged,
454			trail.StatusClosed,
455		}
456		if len(filter) == 0 {
457			return order
458		}
459	
460		allowed := make(map[trail.Status]bool, len(filter))
461		for _, status := range filter {
462			allowed[status] = true
463		}
464		var filtered []trail.Status
465		for _, status := range order {
466			if allowed[status] {
467				filtered = append(filtered, status)
468			}
469		}
470		return filtered
471	}
472	
473	func trailStatusListDisplay(statuses []trail.Status) string {
474		parts := make([]string, len(statuses))
475		for i, status := range statuses {
476			parts[i] = trailStatusDisplay(status)
477		}
478		return strings.Join(parts, ", ")
479	}
480	
481	func trailStatusListTitle(statuses []trail.Status) string {
482		display := trailStatusListDisplay(statuses)
483		if display == "" {
484			return ""
485		}
486		return strings.ToUpper(display[:1]) + display[1:]
487	}
488	
489	func trailStatusDisplay(status trail.Status) string {
490		return strings.ReplaceAll(string(status), "_", " ")
491	}
492	
493	func trailStatusTitle(status trail.Status) string {
494		display := trailStatusDisplay(status)
495		if display == "" {
496			return ""
497		}
498		return strings.ToUpper(display[:1]) + display[1:]
499	}
