530	//nolint:cyclop // sequential steps for creating a trail — splitting would obscure the flow
531	func runTrailCreate(cmd *cobra.Command, title, body, base, branch, statusStr string, checkout bool) error {
532		ctx := cmd.Context()
533		w := cmd.OutOrStdout()
534		errW := cmd.ErrOrStderr()
535	
536		// --- Phase 1: Local git operations (no API calls) ---
537	
538		repo, err := strategy.OpenRepository(ctx)
539		if err != nil {
540			return fmt.Errorf("failed to open repository: %w", err)
541		}
542		defer repo.Close()
543	
544		// Determine base branch
545		if base == "" {
546			base = strategy.GetDefaultBranchName(repo)
547			if base == "" {
548				base = defaultBaseBranch
549			}
550		}
551	
552		_, currentBranch, _ := IsOnDefaultBranch(ctx) //nolint:errcheck // best-effort detection
553		interactive := !cmd.Flags().Changed("title") && !cmd.Flags().Changed("branch")
554	
555		if interactive {
556			// Interactive flow: title → body → branch (derived) → status
557			if err := runTrailCreateInteractive(&title, &body, &branch, &statusStr); err != nil {
558				return handleFormCancellation(w, "Trail creation", err)
559			}
560		} else {
561			// Non-interactive: derive missing values from provided flags
562			if branch == "" {
563				if cmd.Flags().Changed("title") {
564					branch = slugifyTitle(title)
565				} else {
566					branch = currentBranch
567				}
568			}
569			if title == "" {
570				title = trail.HumanizeBranchName(branch)
571			}
572		}
573		if branch == "" {
574			return errors.New("branch name is required")
575		}
576	
577		// Create the local branch if it doesn't exist
578		needsCreation := branchNeedsCreation(repo, branch)
579		if needsCreation {
580			if err := createBranch(repo, branch); err != nil {
581				return fmt.Errorf("failed to create branch %q: %w", branch, err)
582			}
583			fmt.Fprintf(w, "Created branch %s\n", branch)
584		} else if currentBranch != branch {
585			fmt.Fprintf(w, "Note: trail will be created for branch %q (not the current branch)\n", branch)
586		}
587	
588		// Push the branch so the API can reference it
589		if needsCreation {
590			if err := pushBranchToOrigin(branch); err != nil {
591				fmt.Fprintf(errW, "Warning: failed to push branch: %v\n", err)
592			} else {
593				fmt.Fprintf(w, "Pushed branch %s to origin\n", branch)
594			}
595		}
596	
597		// --- Phase 2: API operations ---
598	
599		client, err := NewAuthenticatedAPIClient(ctx, trailInsecureHTTP(cmd))
600		if err != nil {
601			return fmt.Errorf("authentication required: %w", err)
602		}
603	
604		forge, owner, repoName, err := resolveTrailRemote(ctx)
605		if err != nil {
606			return err
607		}
608	
609		createReq := api.TrailCreateRequest{
610			Title:      title,
611			Body:       body,
612			BranchName: branch,
613			Base:       base,
614			Status:     statusStr,
615		}
616	
617		resp, err := client.Post(ctx, trailsBasePath(forge, owner, repoName), createReq)
618		if err != nil {
619			return fmt.Errorf("failed to create trail: %w", err)
620		}
621		defer resp.Body.Close()
622		if err := checkTrailResponse(resp); err != nil {
623			return err
624		}
625	
626		var createResp api.TrailCreateResponse
627		if err := api.DecodeJSON(resp, &createResp); err != nil {
628			return fmt.Errorf("failed to decode create response: %w", err)
629		}
630	
631		fmt.Fprintf(w, "Created trail %q for branch %s (ID: %s)\n", createResp.Trail.Title, createResp.Trail.Branch, createResp.Trail.ID)
632	
633		// --- Phase 3: Post-creation local operations ---
634	
635		if needsCreation && currentBranch != branch {
636			shouldCheckout := checkout
637			if !shouldCheckout && !cmd.Flags().Changed("checkout") {
638				// Interactive: ask whether to checkout
639				form := NewAccessibleForm(
640					huh.NewGroup(
641						huh.NewConfirm().
642							Title(fmt.Sprintf("Check out branch %s?", branch)).
643							Value(&shouldCheckout),
644					),
645				)
646				if formErr := form.Run(); formErr == nil && shouldCheckout {
647					checkout = true
648				}
649			}
650			if checkout {
651				if err := CheckoutBranch(ctx, branch); err != nil {
652					return fmt.Errorf("failed to checkout branch %q: %w", branch, err)
653				}
654				fmt.Fprintf(w, "Switched to branch %s\n", branch)
655			}
656		}
657	
658		return nil
659	}
