683	func runTrailUpdate(ctx context.Context, w, errW io.Writer, insecureHTTP bool, statusStr, title, body, branch string, labelAdd, labelRemove []string) error {
684		_ = errW // reserved for future warnings
685	
686		client, err := NewAuthenticatedAPIClient(ctx, insecureHTTP)
687		if err != nil {
688			return fmt.Errorf("authentication required: %w", err)
689		}
690	
691		forge, owner, repoName, err := resolveTrailRemote(ctx)
692		if err != nil {
693			return err
694		}
695	
696		// Determine branch
697		if branch == "" {
698			branch, err = GetCurrentBranch(ctx)
699			if err != nil {
700				return fmt.Errorf("failed to determine current branch: %w", err)
701			}
702		}
703	
704		// Find the trail by branch
705		found, err := findTrailByBranch(ctx, client, forge, owner, repoName, branch)
706		if err != nil {
707			return err
708		}
709		if found == nil {
710			return fmt.Errorf("no trail found for branch %q", branch)
711		}
712	
713		// Interactive mode when no flags are provided
714		noFlags := statusStr == "" && title == "" && body == "" && labelAdd == nil && labelRemove == nil
715		if noFlags {
716			metadata := found.ToMetadata()
717			// Build status options with current value as default.
718			var statusOptions []huh.Option[string]
719			for _, s := range trail.ValidStatuses() {
720				if (s == trail.StatusMerged || s == trail.StatusClosed) && s != metadata.Status {
721					continue
722				}
723				label := string(s)
724				if s == metadata.Status {
725					label += " (current)"
726				}
727				statusOptions = append(statusOptions, huh.NewOption(label, string(s)))
728			}
729			statusStr = string(metadata.Status)
730			title = metadata.Title
731			body = metadata.Body
732	
733			form := NewAccessibleForm(
734				huh.NewGroup(
735					huh.NewSelect[string]().
736						Title("Status").
737						Options(statusOptions...).
738						Value(&statusStr),
739					huh.NewInput().
740						Title("Title").
741						Value(&title),
742					huh.NewText().
743						Title("Body").
744						Value(&body),
745				),
746			)
747			if formErr := form.Run(); formErr != nil {
748				return handleFormCancellation(w, "Trail update", formErr)
749			}
750		}
751	
752		// Validate status if provided
753		if statusStr != "" {
754			status := trail.Status(statusStr)
755			if !status.IsValid() {
756				return fmt.Errorf("invalid status %q: valid values are %s", statusStr, formatValidStatuses())
757			}
758		}
759	
760		// Build update request with only changed fields
761		updateReq := buildTrailUpdateRequest(found, statusStr, title, body, labelAdd, labelRemove)
762	
763		resp, err := client.Patch(ctx, trailsBasePath(forge, owner, repoName)+"/"+found.ID, updateReq)
764		if err != nil {
765			return fmt.Errorf("failed to update trail: %w", err)
766		}
767		defer resp.Body.Close()
768		if err := checkTrailResponse(resp); err != nil {
769			return err
770		}
771	
772		var updateResp api.TrailUpdateResponse
773		if err := api.DecodeJSON(resp, &updateResp); err != nil {
774			return fmt.Errorf("failed to decode update response: %w", err)
775		}
776	
777		fmt.Fprintf(w, "Updated trail for branch %s\n", branch)
778		return nil
779	}
