781	// buildTrailUpdateRequest constructs a PATCH request body from the current trail and the requested changes.
782	func buildTrailUpdateRequest(current *api.TrailResource, statusStr, title, body string, labelAdd, labelRemove []string) api.TrailUpdateRequest {
783		var req api.TrailUpdateRequest
784	
785		if statusStr != "" {
786			req.Status = &statusStr
787		}
788		if title != "" {
789			req.Title = &title
790		}
791		if body != "" {
792			req.Body = &body
793		}
794	
795		// Handle label changes: merge adds, remove removes
796		if len(labelAdd) > 0 || len(labelRemove) > 0 {
797			labels := make([]string, 0, len(current.Labels)+len(labelAdd))
798			labels = append(labels, current.Labels...)
799			for _, l := range labelAdd {
800				found := false
801				for _, existing := range labels {
802					if existing == l {
803						found = true
804						break
805					}
806				}
807				if !found {
808					labels = append(labels, l)
809				}
810			}
811			for _, l := range labelRemove {
812				for i, existing := range labels {
813					if existing == l {
814						labels = append(labels[:i], labels[i+1:]...)
815						break
816					}
817				}
818			}
819			req.Labels = &labels
820		}
821	
822		return req
823	}
