918	func findTrail(ctx context.Context, client *api.Client, forge, owner, repo string, match func(api.TrailResource) bool) (*api.TrailResource, error) {
919		resp, err := client.Get(ctx, trailsBasePath(forge, owner, repo))
920		if err != nil {
921			return nil, fmt.Errorf("list trails: %w", err)
922		}
923		defer resp.Body.Close()
924		if err := checkTrailResponse(resp); err != nil {
925			return nil, err
926		}
927	
928		var listResp api.TrailListResponse
929		if err := api.DecodeJSON(resp, &listResp); err != nil {
930			return nil, fmt.Errorf("decode trail list: %w", err)
931		}
932	
933		for i := range listResp.Trails {
934			if match(listResp.Trails[i]) {
935				return &listResp.Trails[i], nil
936			}
937		}
938		return nil, nil //nolint:nilnil // nil, nil means "not found" — callers check both
939	}
