941	// trailsBasePath returns the API path prefix for trails endpoints
942	// (e.g., "/api/v1/trails/gh/org/repo").
943	func trailsBasePath(forge, owner, repo string) string {
944		return fmt.Sprintf("/api/v1/trails/%s/%s/%s", forge, owner, repo)
945	}
946	
947	// resolveTrailRemote resolves the origin remote and ensures the forge is
948	// known to the trails API. Without this guard, an unmapped host (e.g.
949	// gitlab.com, or a misconfigured entire:// URL with no forge prefix)
950	// produces a malformed `/api/v1/trails//owner/repo` path that the server
951	// rejects with an opaque error instead of a clear "unsupported forge" one.
952	func resolveTrailRemote(ctx context.Context) (forge, owner, repo string, err error) {
953		forge, owner, repo, err = gitremote.ResolveRemoteRepo(ctx, "origin")
954		if err != nil {
955			return "", "", "", fmt.Errorf("failed to resolve repository: %w", err)
956		}
957		if forge == "" {
958			return "", "", "", errors.New("origin remote is not on a forge supported by Entire trails (supported: github.com)")
959		}
960		return forge, owner, repo, nil
961	}
962	
963	// checkTrailResponse checks the API response and returns user-friendly errors.
964	// For auth failures, it appends a hint to re-authenticate while preserving the server's error message.
965	func checkTrailResponse(resp *http.Response) error {
966		if err := api.CheckResponse(resp); err != nil {
967			if resp.StatusCode == http.StatusUnauthorized || resp.StatusCode == http.StatusForbidden {
968				return fmt.Errorf("%w — run 'entire login' to re-authenticate", err)
969			}
970			return fmt.Errorf("trail API: %w", err)
971		}
972		return nil
973	}
974	
975	// slugifyTitle converts a title string into a branch-friendly slug.
976	// Example: "Add user authentication" -> "add-user-authentication"
977	func slugifyTitle(title string) string {
978		s := strings.ToLower(strings.TrimSpace(title))
979		// Replace spaces and underscores with hyphens
980		s = strings.NewReplacer(" ", "-", "_", "-").Replace(s)
981		// Remove anything that's not alphanumeric, hyphen, or slash
982		var b strings.Builder
983		prevHyphen := false
984		for _, r := range s {
985			if (r >= 'a' && r <= 'z') || (r >= '0' && r <= '9') || r == '/' {
986				b.WriteRune(r)
987				prevHyphen = false
988			} else if r == '-' && !prevHyphen {
989				b.WriteRune('-')
990				prevHyphen = true
991			}
992		}
993		return strings.Trim(b.String(), "-")
994	}
995	
996	// branchNeedsCreation checks if a branch exists locally.
997	func branchNeedsCreation(repo *git.Repository, branchName string) bool {
998		_, err := repo.Reference(plumbing.NewBranchReferenceName(branchName), true)
999		return err != nil
1000	}
1001	
1002	// createBranch creates a new local branch pointing at HEAD without checking it out.
1003	func createBranch(repo *git.Repository, branchName string) error {
1004		head, err := repo.Head()
1005		if err != nil {
1006			return fmt.Errorf("failed to get HEAD: %w", err)
1007		}
1008		ref := plumbing.NewHashReference(plumbing.NewBranchReferenceName(branchName), head.Hash())
1009		if err := repo.Storer.SetReference(ref); err != nil {
1010			return fmt.Errorf("failed to create branch ref: %w", err)
1011		}
1012		return nil
1013	}
1014	
1015	// pushBranchToOrigin pushes a branch to the origin remote.
1016	func pushBranchToOrigin(branchName string) error {
1017		ctx, cancel := context.WithTimeout(context.Background(), 2*time.Minute)
1018		defer cancel()
1019		cmd := exec.CommandContext(ctx, "git", "push", "--no-verify", "-u", "origin", branchName)
1020		if output, err := cmd.CombinedOutput(); err != nil {
1021			return fmt.Errorf("%s: %w", strings.TrimSpace(string(output)), err)
1022		}
1023		return nil
1024	}
