434	func resolveTrailReviewTarget(ctx context.Context, client *api.Client, selector string) (trailReviewTarget, error) {
435		host, owner, repo, err := resolveTrailRemote(ctx)
436		if err != nil {
437			return trailReviewTarget{}, err
438		}
439	
440		selector = strings.TrimSpace(selector)
441		var found *api.TrailResource
442		if selector != "" {
443			found, err = findTrailBySelector(ctx, client, host, owner, repo, selector)
444			if err != nil {
445				return trailReviewTarget{}, err
446			}
447			if found == nil {
448				return trailReviewTarget{}, fmt.Errorf("no trail %q found in %s/%s/%s (run 'entire trail list --status any')", selector, host, owner, repo)
449			}
450		} else {
451			branch, branchErr := GetCurrentBranch(ctx)
452			if branchErr != nil {
453				return trailReviewTarget{}, fmt.Errorf("%w: no trail selector given and current branch is unknown: %w\nhint: run 'entire trail list --status any' or pass --trail <number|id|branch>", errTrailReviewDefaultTargetNotFound, branchErr)
454			}
455			found, err = findTrailByBranch(ctx, client, host, owner, repo, branch)
456			if err != nil {
457				return trailReviewTarget{}, err
458			}
459			if found == nil {
460				return trailReviewTarget{}, fmt.Errorf("%w: no trail found for current branch %q\nhint: run 'entire trail create', 'entire trail list --status any', or pass --trail <number|id|branch>", errTrailReviewDefaultTargetNotFound, branch)
461			}
462		}
463		if found.ID == "" {
464			return trailReviewTarget{}, errors.New("trail has no id yet")
465		}
466		return trailReviewTarget{Host: host, Owner: owner, Repo: repo, Trail: *found}, nil
467	}
