651	func buildTrailReviewCommentLocation(opts trailReviewCommentAddOptions) (api.TrailReviewLocationCreateRequest, error) {
652		filePath := strings.TrimSpace(opts.FilePath)
653		line := opts.Line
654		if line < 0 || opts.StartLine < 0 || opts.EndLine < 0 {
655			return api.TrailReviewLocationCreateRequest{}, errors.New("line numbers must be non-negative")
656		}
657		if opts.StartLine > 0 {
658			if line > 0 {
659				return api.TrailReviewLocationCreateRequest{}, errors.New("pass either --line or --start-line, not both")
660			}
661			line = opts.StartLine
662		}
663		if filePath == "" && (line > 0 || opts.EndLine > 0) {
664			return api.TrailReviewLocationCreateRequest{}, errors.New("--line/--start-line/--end-line require --file")
665		}
666		if opts.EndLine > 0 && line == 0 {
667			return api.TrailReviewLocationCreateRequest{}, errors.New("--end-line requires --line or --start-line")
668		}
669		if opts.EndLine > 0 && opts.EndLine < line {
670			return api.TrailReviewLocationCreateRequest{}, errors.New("--end-line must be greater than or equal to the start line")
671		}
672	
673		loc := api.TrailReviewLocationCreateRequest{Granularity: "whole_change"}
674		if filePath == "" {
675			return loc, nil
676		}
677		loc.Granularity = "file"
678		loc.FilePath = stringPtr(filePath)
679		if line > 0 {
680			loc.Granularity = "line"
681			loc.StartLine = &line
682			if opts.EndLine > 0 {
683				loc.EndLine = &opts.EndLine
684				if opts.EndLine != line {
685					loc.Granularity = "range"
686				}
687			}
688		}
689		return loc, nil
690	}
