712	func resolveTrailReviewComment(ctx context.Context, client *api.Client, trailID, commentID string) (api.TrailReviewComment, error) {
713		opts := trailReviewListOptions{
714			Status:           trailReviewStatusAny,
715			Stale:            trailReviewStaleAny,
716			IncludeDismissed: true,
717			Limit:            defaultTrailReviewLimit,
718		}
719		var matches []api.TrailReviewComment
720		for {
721			comments, hasMore, err := fetchTrailReviewComments(ctx, client, trailID, opts)
722			if err != nil {
723				return api.TrailReviewComment{}, err
724			}
725			for _, comment := range comments {
726				if comment.ID == commentID {
727					return comment, nil
728				}
729				if strings.HasPrefix(comment.ID, commentID) {
730					matches = append(matches, comment)
731				}
732			}
733			if !hasMore {
734				break
735			}
736			opts.Offset += opts.Limit
737		}
738		switch len(matches) {
739		case 0:
740			return api.TrailReviewComment{}, fmt.Errorf("no finding %q found", commentID)
741		case 1:
742			return matches[0], nil
743		default:
744			ids := make([]string, len(matches))
745			for i := range matches {
746				ids[i] = matches[i].ID
747			}
748			sort.Strings(ids)
749			return api.TrailReviewComment{}, fmt.Errorf("ambiguous finding %q (matches: %s)", commentID, strings.Join(ids, ", "))
750		}
751	}
