771	func fetchTrailReviewState(ctx context.Context, client *api.Client, trailID, reviewID string) (api.TrailReviewStateResponse, error) {
772		var merged api.TrailReviewStateResponse
773		cursor := ""
774		seenCursors := map[string]bool{}
775		for {
776			resp, err := client.Get(ctx, trailReviewStatePath(trailID, reviewID, cursor))
777			if err != nil {
778				return api.TrailReviewStateResponse{}, fmt.Errorf("get review state: %w", err)
779			}
780			var page api.TrailReviewStateResponse
781			decodeErr := func() error {
782				defer resp.Body.Close()
783				if err := checkTrailResponse(resp); err != nil {
784					return err
785				}
786				if err := api.DecodeJSON(resp, &page); err != nil {
787					return fmt.Errorf("decode review state: %w", err)
788				}
789				return nil
790			}()
791			if decodeErr != nil {
792				return api.TrailReviewStateResponse{}, decodeErr
793			}
794	
795			if cursor == "" {
796				merged = page
797			} else {
798				merged.Comments = append(merged.Comments, page.Comments...)
799				merged.NextCursor = page.NextCursor
800				merged.EventCursor = page.EventCursor
801			}
802	
803			if page.NextCursor == nil || strings.TrimSpace(*page.NextCursor) == "" {
804				merged.NextCursor = nil
805				break
806			}
807			cursor = strings.TrimSpace(*page.NextCursor)
808			if seenCursors[cursor] {
809				return api.TrailReviewStateResponse{}, fmt.Errorf("review state pagination repeated cursor %q", cursor)
810			}
811			seenCursors[cursor] = true
812		}
813		return merged, nil
814	}
