842	func applyTrailReviewSuggestions(ctx context.Context, comment api.TrailReviewComment, checkOnly bool, w io.Writer) (int, error) {
843		if len(comment.SuggestedChanges) == 0 {
844			return 0, fmt.Errorf("finding %s has no suggested changes", comment.ID)
845		}
846		combinedPatch, supported, err := combinedSafeUnifiedDiffPatch(comment, w)
847		if err != nil {
848			return 0, err
849		}
850		if supported == 0 {
851			return 0, fmt.Errorf("finding %s has no supported unified_diff suggested changes", comment.ID)
852		}
853		if err := runGitApply(ctx, combinedPatch, true); err != nil {
854			return 0, fmt.Errorf("suggested changes for finding %s do not apply cleanly: %w", comment.ID, err)
855		}
856		if checkOnly {
857			return supported, nil
858		}
859		if err := runGitApply(ctx, combinedPatch, false); err != nil {
860			return 0, fmt.Errorf("apply suggested changes for finding %s: %w", comment.ID, err)
861		}
862		return supported, nil
863	}
864	
865	func combinedSafeUnifiedDiffPatch(comment api.TrailReviewComment, w io.Writer) (string, int, error) {
866		var combined strings.Builder
867		supported := 0
868		for _, change := range comment.SuggestedChanges {
869			patch := strings.TrimSpace(stringPtrValue(change.Patch))
870			if change.ChangeType != "unified_diff" || patch == "" {
871				fmt.Fprintf(w, "Skipping suggested change %s (%s): only unified_diff patches are supported.\n", change.ID, change.ChangeType)
872				continue
873			}
874			if err := validateUnifiedDiffPatchPaths(patch); err != nil {
875				return "", 0, fmt.Errorf("suggested change %s has unsafe patch path: %w", change.ID, err)
876			}
877			if combined.Len() > 0 {
878				combined.WriteByte('\n')
879			}
880			combined.WriteString(patch)
881			combined.WriteByte('\n')
882			supported++
883		}
884		return combined.String(), supported, nil
885	}
886	
887	func validateUnifiedDiffPatchPaths(patchText string) error {
888		scanner := bufio.NewScanner(strings.NewReader(patchText))
889		scanner.Buffer(make([]byte, 0, 64*1024), 1<<20)
890		for scanner.Scan() {
891			line := scanner.Text()
892			for _, p := range patchHeaderPaths(line) {
893				if err := validatePatchPath(p); err != nil {
894					return err
895				}
896			}
897		}
898		if err := scanner.Err(); err != nil {
899			return fmt.Errorf("scan patch: %w", err)
900		}
901		return nil
902	}
903	
904	func patchHeaderPaths(line string) []string {
905		switch {
906		case strings.HasPrefix(line, "diff --git "):
907			fields := strings.Fields(strings.TrimPrefix(line, "diff --git "))
908			if len(fields) >= 2 {
909				return []string{fields[0], fields[1]}
910			}
911		case strings.HasPrefix(line, "--- ") || strings.HasPrefix(line, "+++ "):
912			return []string{patchHeaderPath(line[4:])}
913		case strings.HasPrefix(line, "rename from "):
914			return []string{strings.TrimSpace(strings.TrimPrefix(line, "rename from "))}
915		case strings.HasPrefix(line, "rename to "):
916			return []string{strings.TrimSpace(strings.TrimPrefix(line, "rename to "))}
917		case strings.HasPrefix(line, "copy from "):
918			return []string{strings.TrimSpace(strings.TrimPrefix(line, "copy from "))}
919		case strings.HasPrefix(line, "copy to "):
920			return []string{strings.TrimSpace(strings.TrimPrefix(line, "copy to "))}
921		}
922		return nil
923	}
924	
925	func patchHeaderPath(raw string) string {
926		raw = strings.TrimSpace(raw)
927		if beforeTab, _, ok := strings.Cut(raw, "\t"); ok {
928			raw = beforeTab
929		}
930		return raw
931	}
932	
933	func validatePatchPath(raw string) error {
934		p := strings.TrimSpace(raw)
935		if p == "" || p == "/dev/null" {
936			return nil
937		}
938		if unquoted, err := strconv.Unquote(p); err == nil {
939			p = unquoted
940		}
941		p = strings.TrimPrefix(p, "a/")
942		p = strings.TrimPrefix(p, "b/")
943		p = strings.ReplaceAll(p, "\\", "/")
944		if strings.HasPrefix(p, "/") {
945			return fmt.Errorf("absolute path %q is not allowed", raw)
946		}
947		clean := path.Clean(p)
948		if clean == "." || clean == "" {
949			return nil
950		}
951		if clean == ".." || strings.HasPrefix(clean, "../") {
952			return fmt.Errorf("path %q escapes the repository", raw)
953		}
954		for _, part := range strings.Split(clean, "/") {
955			// EqualFold guards case-insensitive filesystems (default macOS/Windows)
956			// where ".GIT/config" would otherwise slip past an exact match.
957			if strings.EqualFold(part, ".git") {
958				return fmt.Errorf("path %q targets .git metadata", raw)
959			}
960		}
961		return nil
962	}
963	
964	func runGitApply(ctx context.Context, patch string, checkOnly bool) error {
965		root, err := paths.WorktreeRoot(ctx)
966		if err != nil {
967			return fmt.Errorf("resolve worktree root: %w", err)
968		}
969		args := []string{"-C", root, "apply"}
970		if checkOnly {
971			args = append(args, "--check")
972		}
973		cmd := exec.CommandContext(ctx, "git", args...)
974		cmd.Stdin = bytes.NewBufferString(patch + "\n")
975		out, err := cmd.CombinedOutput()
976		if err != nil {
977			msg := strings.TrimSpace(string(out))
978			if msg != "" {
979				return fmt.Errorf("git apply: %w: %s", err, msg)
980			}
981			return fmt.Errorf("git apply: %w", err)
982		}
983		return nil
984	}
