1010	func resolveGitRev(ctx context.Context, ref string) (string, error) {
1011		root, err := paths.WorktreeRoot(ctx)
1012		if err != nil {
1013			return "", fmt.Errorf("resolve worktree root: %w", err)
1014		}
1015		cmd := exec.CommandContext(ctx, "git", "-C", root, "rev-parse", ref)
1016		out, err := cmd.Output()
1017		if err != nil {
1018			return "", fmt.Errorf("git rev-parse %s: %w", ref, err)
1019		}
1020		sha := strings.TrimSpace(string(out))
1021		if sha == "" {
1022			return "", fmt.Errorf("git rev-parse %s: empty output", ref)
1023		}
1024		return sha, nil
1025	}
