1340	func truncateOneLine(s string, maxRunes int) string {
1341		s = strings.ReplaceAll(s, "\r\n", " ")
1342		s = strings.ReplaceAll(s, "\n", " ")
1343		s = strings.Join(strings.Fields(s), " ")
1344		runes := []rune(s)
1345		if len(runes) <= maxRunes {
1346			return s
1347		}
1348		return string(runes[:maxRunes]) + "…"
1349	}
