21	// SSE control events for the agent-native finding stream. Domain events
22	// (for example "session.started" or "comment.created") are emitted as their
23	// code_review_events.event_type values.
24	const (
25		sseEventReady     = "ready"
26		sseEventReconnect = "reconnect"
27		sseEventForbidden = "forbidden"
28		sseEventError     = "error"
