31	// reconnectBackoffInitial / reconnectBackoffCap bound the exponential backoff
32	// used after network errors. The server's max stream duration (~50s) closes
33	// cleanly with an `event: reconnect`; in that case we reconnect immediately
34	// with no backoff.
35	const (
36		reconnectBackoffInitial = 500 * time.Millisecond
37		reconnectBackoffCap     = 30 * time.Second
38	)
