86	func runTrailWatch(cmd *cobra.Command, number int, jsonOutput, showPings, once bool) error {
87		ctx := cmd.Context()
88		client, err := NewAuthenticatedAPIClient(ctx, trailInsecureHTTP(cmd))
89		if err != nil {
90			return fmt.Errorf("authentication required: %w", err)
91		}
92	
93		trailID, description, err := resolveTrailWatchTarget(ctx, client, number)
94		if err != nil {
95			return err
96		}
97		return runTrailWatchResolved(cmd, client, trailID, description, jsonOutput, showPings, once)
98	}
