100	func runTrailWatchResolved(cmd *cobra.Command, client *api.Client, trailID, description string, jsonOutput, showPings, once bool) error {
101		ctx := cmd.Context()
102		w := cmd.OutOrStdout()
103		errW := cmd.ErrOrStderr()
104		streamPath := reviewEventsPath(trailID)
105	
106		fmt.Fprintf(errW, "Watching %s — Ctrl+C to stop\n", description)
107	
108		backoff := reconnectBackoffInitial
109		lastEventID := ""
110	
111		for {
112			closeReason, lastSeenID, err := streamOnce(ctx, client, streamPath, lastEventID, jsonOutput, showPings, w, errW)
113			if lastSeenID != "" {
114				lastEventID = lastSeenID
115			}
116	
117			// Context cancelled (Ctrl+C) — exit cleanly.
118			if ctx.Err() != nil {
119				return nil //nolint:nilerr // ctx.Err() is the expected cancellation path; surface as clean exit
120			}
121	
122			if once {
123				switch closeReason {
124				case streamCloseTerminal:
125					return err
126				case streamCloseForbidden:
127					return NewSilentError(errors.New("stream access revoked"))
128				case streamCloseError:
129					if err == nil {
130						err = errors.New("stream error reported by server")
131					}
132					return NewSilentError(err)
133				case streamCloseTransport:
134					return err
135				case streamCloseReconnect, streamCloseDone:
136					return nil
137				}
138			}
139	
140			switch closeReason {
141			case streamCloseTerminal:
142				return err
143			case streamCloseDone:
144				return nil
145			case streamCloseForbidden:
146				return NewSilentError(errors.New("stream access revoked"))
147			case streamCloseReconnect:
148				// Clean server-initiated reconnect (max_duration). No backoff.
149				backoff = reconnectBackoffInitial
150				continue
151			case streamCloseError:
152				// Server emitted `event: error` — reconnect with backoff.
153				fmt.Fprintf(errW, "stream error reported by server, reconnecting in %s\n", backoff)
154			case streamCloseTransport:
155				// Network/transport error.
156				if err != nil {
157					fmt.Fprintf(errW, "stream disconnected (%v), reconnecting in %s\n", err, backoff)
158				}
159			}
160	
161			// Sleep with cancellation.
162			select {
163			case <-ctx.Done():
164				return nil
165			case <-time.After(backoff):
166			}
167			backoff *= 2
168			if backoff > reconnectBackoffCap {
169				backoff = reconnectBackoffCap
170			}
171		}
172	}
