218	func trailWatchDescription(forge, owner, repo string, number int, trailID string) string {
219		if number > 0 {
220			return fmt.Sprintf("trail #%d (%s/%s/%s, id %s)", number, forge, owner, repo, trailID)
221		}
222		return fmt.Sprintf("trail %s (%s/%s/%s)", trailID, forge, owner, repo)
223	}
224	
225	func reviewEventsPath(trailID string) string {
226		return "/api/v1/trails/" + url.PathEscape(trailID) + "/reviews/events"
227	}
228	
229	type streamCloseReason int
230	
231	const (
232		streamCloseTransport streamCloseReason = iota // network/transport error
233		streamCloseReconnect                          // server `event: reconnect`
234		streamCloseForbidden                          // server `event: forbidden`
235		streamCloseError                              // server `event: error`
236		streamCloseDone                               // context cancellation
237		streamCloseTerminal                           // non-recoverable HTTP status (401/403/404/410)
238	)
239	
240	// terminalHTTPStatuses are HTTP response codes for which retrying the SSE
241	// stream cannot succeed: auth failures (401/403) and resource-not-found-style
242	// errors (404/410). 429 is intentionally *not* terminal — it's a transient
243	// rate-limit signal that should back off and retry.
244	var terminalHTTPStatuses = [...]int{
245		http.StatusUnauthorized, // 401
246		http.StatusForbidden,    // 403
247		http.StatusNotFound,     // 404
248		http.StatusGone,         // 410
249	}
250	
251	func isTerminalHTTPError(err error) bool {
252		for _, code := range terminalHTTPStatuses {
253			if api.IsHTTPErrorStatus(err, code) {
254				return true
255			}
256		}
257		return false
258	}
259	
260	// streamOnce opens a single SSE connection, prints events until it closes for
261	// any reason, and returns the close reason plus the last `id:` observed (so
262	// the caller can pass it as `Last-Event-ID` on reconnect).
263	//
264	//nolint:cyclop,gocognit // SSE framing parser is naturally branchy; splitting hurts readability
265	func streamOnce(
266		ctx context.Context,
267		client *api.Client,
268		path string,
269		lastEventID string,
270		jsonOutput, showPings bool,
271		w, errW io.Writer,
272	) (streamCloseReason, string, error) {
273		headers := http.Header{}
274		headers.Set("Accept", "text/event-stream")
275		headers.Set("Cache-Control", "no-cache")
276		if lastEventID != "" {
277			headers.Set("Last-Event-ID", lastEventID)
278		}
279	
280		resp, err := client.GetStream(ctx, path, headers)
281		if err != nil {
282			return streamCloseTransport, "", fmt.Errorf("open SSE stream: %w", err)
283		}
284		defer resp.Body.Close()
285	
286		if err := checkTrailResponse(resp); err != nil {
287			// Terminal: surface the error and don't reconnect. 429 deliberately
288			// falls through to streamCloseTransport so the caller backs off.
289			if isTerminalHTTPError(err) {
290				return streamCloseTerminal, "", err
291			}
292			return streamCloseTransport, "", err
293		}
294	
295		scanner := bufio.NewScanner(resp.Body)
296		// SSE frames can be larger than the default 64KiB scanner buffer when a
297		// review event carries long comment bodies; bump to 1 MiB to match the API's
298		// per-comment limits.
299		scanner.Buffer(make([]byte, 0, 64*1024), 1<<20)
300	
301		var (
302			eventName  string
303			dataLines  []string
304			eventID    string // id of the in-progress frame (reset on flush)
305			lastSeenID string // most recent SSE id from any frame that includes one
306		)
307	
308		flush := func() (streamCloseReason, bool) {
309			defer func() {
310				eventName = ""
311				dataLines = nil
312				eventID = ""
313			}()
314			if eventName == "" && len(dataLines) == 0 {
315				return streamCloseTransport, false
316			}
317			data := strings.Join(dataLines, "\n")
318			printSSEEvent(w, errW, eventName, data, jsonOutput)
319	
320			if eventID != "" {
321				lastSeenID = eventID
322			}
323	
324			switch eventName {
325			case sseEventReconnect:
326				return streamCloseReconnect, true
327			case sseEventForbidden:
328				return streamCloseForbidden, true
329			case sseEventError:
330				return streamCloseError, true
331			}
332			return streamCloseTransport, false
333		}
334	
335		for scanner.Scan() {
336			line := scanner.Text()
337	
338			// Blank line dispatches the event.
339			if line == "" {
340				if reason, done := flush(); done {
341					return reason, lastSeenID, nil
342				}
343				continue
344			}
345	
346			// Comment / keepalive line.
347			if strings.HasPrefix(line, ":") {
348				if showPings {
349					fmt.Fprintln(errW, "ping:", strings.TrimSpace(strings.TrimPrefix(line, ":")))
350				}
351				continue
352			}
353	
354			field, value, ok := strings.Cut(line, ":")
355			if !ok {
356				// Field-only line (no colon) — per spec the value is empty.
357				field = line
358				value = ""
359			}
360			// Per SSE spec: a single leading space after the colon is ignored.
361			value = strings.TrimPrefix(value, " ")
362	
363			switch field {
364			case "event":
365				eventName = value
366			case "data":
367				dataLines = append(dataLines, value)
368			case "id":
369				eventID = value
370			case "retry":
371				// Ignored — we manage backoff client-side.
372			}
373		}
374	
375		if err := scanner.Err(); err != nil {
376			// Context cancellation surfaces here as a wrapped "context canceled".
377			if errors.Is(err, context.Canceled) || ctx.Err() != nil {
378				return streamCloseDone, lastSeenID, nil
379			}
380			return streamCloseTransport, lastSeenID, fmt.Errorf("read SSE stream: %w", err)
381		}
382		return streamCloseTransport, lastSeenID, io.ErrUnexpectedEOF
383	}
384	
385	// printSSEEvent renders a single SSE event in either human-readable or
386	// json-line form. `data` may be empty (e.g. for the rare frame with only an
387	// `event:` line) — we still print something so the caller sees it.
388	func printSSEEvent(w, errW io.Writer, eventName, data string, jsonOutput bool) {
389		if jsonOutput {
390			// Emit a JSON envelope so consumers can reliably parse with
391			// `jq`/scripts. The data field is preserved verbatim if it isn't
392			// valid JSON; otherwise it's inlined as a sub-object.
393			envelope := map[string]any{"event": eventName}
394			if data != "" {
395				var sub any
396				if err := json.Unmarshal([]byte(data), &sub); err == nil {
397					envelope["data"] = sub
398				} else {
399					envelope["data"] = data
400				}
401			}
402			out, err := json.Marshal(envelope)
403			if err != nil {
404				fmt.Fprintf(errW, "failed to marshal event: %v\n", err)
405				return
406			}
407			fmt.Fprintln(w, string(out))
408			return
409		}
410	
411		switch eventName {
412		case sseEventReady:
413			printReadyEvent(w, data)
414			return
415		case sseEventReconnect:
416			fmt.Fprintln(errW, "↻ server requested reconnect")
417			return
418		case sseEventForbidden:
419			fmt.Fprintln(errW, "✖ stream access revoked")
420			return
421		case sseEventError:
422			printStreamError(errW, data)
423			return
424		}
425	
426		if ev, ok := parseReviewStreamEvent(eventName, data); ok {
427			printReviewStreamEvent(w, ev)
428			return
429		}
430	
431		// Fallback for unknown events or unparseable payloads: print raw.
432		fmt.Fprintf(w, "%s: %s\n", eventName, truncateForLog(data, 500))
433	}
434	
435	type reviewReadyPayload struct {
436		TrailID string `json:"trail_id"`
437		Cursor  int    `json:"cursor"`
438	}
439	
440	type reviewStreamEvent struct {
441		ID              any            `json:"id"`
442		TrailID         string         `json:"trail_id"`
443		ReviewSessionID *string        `json:"review_session_id"`
444		ActorID         string         `json:"actor_id"`
445		EventType       string         `json:"event_type"`
446		TargetType      string         `json:"target_type"`
447		TargetID        string         `json:"target_id"`
448		Payload         map[string]any `json:"payload"`
449		CreatedAt       time.Time      `json:"created_at"`
450	}
451	
452	func printReadyEvent(w io.Writer, data string) {
453		var p reviewReadyPayload
454		if err := json.Unmarshal([]byte(data), &p); err == nil {
455			parts := []string{"● connected"}
456			if p.TrailID != "" {
457				parts = append(parts, "to trail "+p.TrailID)
458			}
459			if p.Cursor > 0 {
460				parts = append(parts, fmt.Sprintf("after event %d", p.Cursor))
461			}
462			fmt.Fprintln(w, strings.Join(parts, " "))
463			return
464		}
465		fmt.Fprintf(w, "ready: %s\n", truncateForLog(data, 500))
466	}
467	
468	func printStreamError(errW io.Writer, data string) {
469		var p struct {
470			Message string `json:"message"`
471		}
472		if jerr := json.Unmarshal([]byte(data), &p); jerr != nil {
473			// Best-effort: server payload may be missing or malformed; we still
474			// want to surface that an error event arrived.
475			fmt.Fprintf(errW, "Warning: malformed error payload: %v\n", jerr)
476		}
477		if p.Message != "" {
478			fmt.Fprintf(errW, "✖ stream error: %s\n", p.Message)
479		} else {
480			fmt.Fprintln(errW, "✖ stream error")
481		}
482	}
483	
484	func parseReviewStreamEvent(eventName, data string) (reviewStreamEvent, bool) {
485		var ev reviewStreamEvent
486		if err := json.Unmarshal([]byte(data), &ev); err != nil {
487			return ev, false
488		}
489		if ev.EventType == "" {
490			ev.EventType = eventName
491		}
492		if ev.EventType == "" && ev.TargetType == "" && ev.TargetID == "" {
493			return ev, false
494		}
495		return ev, true
496	}
497	
498	func printReviewStreamEvent(w io.Writer, ev reviewStreamEvent) {
499		prefix := ""
500		if !ev.CreatedAt.IsZero() {
501			prefix = "[" + ev.CreatedAt.Local().Format("15:04:05") + "] "
502		}
503		actor := ev.ActorID
504		if actor == "" {
505			actor = "unknown actor"
506		}
507	
508		switch ev.EventType {
509		case "code_version.created":
510			fmt.Fprintf(w, "%scode version %s created (head %s)\n", prefix, ev.TargetID, payloadString(ev.Payload, "head_sha"))
511		case "code_version.base_sha_set":
512			fmt.Fprintf(w, "%scode version %s base set to %s\n", prefix, ev.TargetID, payloadString(ev.Payload, "base_sha"))
513		case "session.started":
514			fmt.Fprintf(w, "%ssession started by %s (code version %s)\n", prefix, actor, payloadString(ev.Payload, "code_version_id"))
515		case "session.ended":
516			reason := payloadString(ev.Payload, "reason")
517			if reason != "" {
518				fmt.Fprintf(w, "%ssession ended by %s (%s)\n", prefix, actor, reason)
519			} else {
520				fmt.Fprintf(w, "%ssession ended by %s\n", prefix, actor)
521			}
522		case "comment.created":
523			file := payloadString(ev.Payload, "file_path")
524			severity := payloadString(ev.Payload, "severity")
525			switch {
526			case file != "" && severity != "":
527				fmt.Fprintf(w, "%sfinding created by %s on %s (%s) — %s\n", prefix, actor, file, severity, ev.TargetID)
528			case file != "":
529				fmt.Fprintf(w, "%sfinding created by %s on %s — %s\n", prefix, actor, file, ev.TargetID)
530			default:
531				fmt.Fprintf(w, "%sfinding created by %s — %s\n", prefix, actor, ev.TargetID)
532			}
533		case "comment.status_changed":
534			fmt.Fprintf(w, "%sfinding %s status %s → %s\n", prefix, ev.TargetID, payloadString(ev.Payload, "from"), payloadString(ev.Payload, "to"))
535		case "comment.updated":
536			fmt.Fprintf(w, "%sfinding %s updated by %s\n", prefix, ev.TargetID, actor)
537		case "comment.stale_checked":
538			fmt.Fprintf(w, "%sfinding %s marked %s (%s)\n", prefix, ev.TargetID, payloadString(ev.Payload, "outcome"), payloadString(ev.Payload, "reason"))
539		case "suggested_change.created":
540			fmt.Fprintf(w, "%ssuggested change %s created for finding %s (%s)\n", prefix, ev.TargetID, payloadString(ev.Payload, "review_comment_id"), payloadString(ev.Payload, "change_type"))
541		case "suggested_change.updated":
542			fmt.Fprintf(w, "%ssuggested change %s updated by %s\n", prefix, ev.TargetID, actor)
543		case "suggested_change.check_result", "suggested_change.apply_result":
544			fmt.Fprintf(w, "%s%s for %s: %s\n", prefix, ev.EventType, payloadString(ev.Payload, "suggested_change_id"), payloadString(ev.Payload, "status"))
545		case "thread.created":
546			fmt.Fprintf(w, "%sthread %s created for finding %s\n", prefix, ev.TargetID, payloadString(ev.Payload, "review_comment_id"))
547		case "thread.message_added":
548			fmt.Fprintf(w, "%sthread message %s added by %s\n", prefix, ev.TargetID, actor)
549		case "thread.message_edited":
550			fmt.Fprintf(w, "%sthread message %s edited by %s\n", prefix, ev.TargetID, actor)
551		case "comment.linked":
552			fmt.Fprintf(w, "%sfinding link created: %s → %s\n", prefix, payloadString(ev.Payload, "source_comment_id"), payloadString(ev.Payload, "target_comment_id"))
553		case "comment.unlinked":
554			fmt.Fprintf(w, "%sfinding link removed: %s → %s\n", prefix, payloadString(ev.Payload, "source_comment_id"), payloadString(ev.Payload, "target_comment_id"))
555		default:
556			fmt.Fprintf(w, "%s%s %s/%s by %s\n", prefix, ev.EventType, ev.TargetType, ev.TargetID, actor)
557		}
558	}
559	
560	func payloadString(payload map[string]any, key string) string {
561		if payload == nil {
562			return ""
563		}
564		v, ok := payload[key]
565		if !ok || v == nil {
566			return ""
567		}
568		switch t := v.(type) {
569		case string:
570			return t
571		case fmt.Stringer:
572			return t.String()
573		default:
574			return fmt.Sprint(t)
575		}
576	}
577	
578	// truncateForLog clips body text on a rune boundary so a single multi-line
579	// payload doesn't blow up the watch view. Newlines collapse to spaces.
580	func truncateForLog(s string, maxRunes int) string {
581		s = strings.ReplaceAll(s, "\r\n", " ")
582		s = strings.ReplaceAll(s, "\n", " ")
583		rs := []rune(s)
584		if len(rs) <= maxRunes {
585			return s
586		}
587		return string(rs[:maxRunes]) + "…"
588	}
