import json
spec=json.load(open('/tmp/data-api.json'))
paths=spec['paths']; comps=spec['components']['schemas']
def deref(s):
    while isinstance(s,dict) and '\$ref' in s: s=comps.get(s['\$ref'].split('/')[-1],{})
    return s
def schema_of(op):
    c=op.get('requestBody',{}).get('content',{}).get('application/json',{})
    return deref(c.get('schema',{}))
def resp_of(op):
    for code in('200','201'):
        r=op.get('responses',{}).get(code)
        if r:
            return deref(r.get('content',{}).get('application/json',{}).get('schema',{}))
    return {}

# POST /reviews (create review)
print('### POST /reviews  req props:', list(schema_of(paths['/api/v1/trails/{trail_id}/reviews']['post']).get('properties',{})))
print('### POST /reviews  resp props:', list(resp_of(paths['/api/v1/trails/{trail_id}/reviews']['post']).get('properties',{})))
print()
# POST /reviews/{id}/comments  comments item
body=schema_of(paths['/api/v1/trails/{trail_id}/reviews/{id}/comments']['post'])
