// Temporary, read-only live probe: confirms whether the single-trail detail
// endpoint (spec param {number}) accepts the trail's number, its id, or both.
// Run with: ENTIRE_LIVE_PROBE=1 go test ./cmd/entire/cli/ -run TestZZLiveTrailDetailProbe -count=1 -v
func TestZZLiveTrailDetailProbe(t *testing.T) {
	if os.Getenv("ENTIRE_LIVE_PROBE") == "" {
		t.Skip("set ENTIRE_LIVE_PROBE=1 to run the live probe")
	}
	ctx := context.Background()
	client, err := NewAuthenticatedAPIClient(ctx, false)
	if err != nil {
		t.Fatalf("client: %v", err)
	}
	base := "/api/v1/trails/github.com/entireio/cli/"
	for _, id := range []string{"546", "019eaef0-8039-7a31-b7f5-61921b1383cd"} {
		resp, err := client.Get(ctx, base+id)
		if err != nil {
			t.Logf("GET %s -> transport error: %v", id, err)
			continue
		}
		body, _ := io.ReadAll(resp.Body)
		resp.Body.Close()
		snippet := string(body)
		if len(snippet) > 200 {
			snippet = snippet[:200]
		}
		t.Logf("GET %q -> %d  body: %s", id, resp.StatusCode, snippet)
	}
}

